import { getServerSession } from 'next-auth/next';
import { authOptions } from '../auth/[...nextauth]';
import dbConnect from '@/lib/mongodb';
import Product from '@/models/Product';
import { z } from 'zod';
import { HILGOD_PRODUCTS } from '@/lib/products-data';

// Validation schema for product creation
const productSchema = z.object({
  name: z.string().min(2).max(200),
  description: z.string().min(10).max(2000),
  price: z.number().min(0),
  images: z.array(z.string().url()).min(1),
  category: z.string().min(1),
  stock: z.number().min(0).default(0),
});

export default async function handler(req, res) {
  const { method } = req;

  if (method === 'GET') {
    const { category, search, page = 1, limit = 20 } = req.query;

    let useFallback = false;
    try {
      await dbConnect();
    } catch (dbError) {
      console.warn("Database connection failed, using fallback data.");
      useFallback = true;
    }

    if (useFallback) {
      let filteredProducts = [...HILGOD_PRODUCTS];
      if (category) {
        const catArray = category.split(',');
        filteredProducts = filteredProducts.filter(p => catArray.includes(p.category));
      }
      if (req.query.subcategory) {
        const subCatArray = req.query.subcategory.split(',');
        filteredProducts = filteredProducts.filter(p => subCatArray.includes(p.subcategory));
      }
      if (search) {
        const lowerSearch = search.toLowerCase();
        filteredProducts = filteredProducts.filter(p => 
          p.name.toLowerCase().includes(lowerSearch) || 
          p.description.toLowerCase().includes(lowerSearch) ||
          p.brand.toLowerCase().includes(lowerSearch) ||
          (p.subcategory && p.subcategory.toLowerCase().includes(lowerSearch))
        );
      }
      
      const skip = (parseInt(page) - 1) * parseInt(limit);
      const paginatedProducts = filteredProducts.slice(skip, skip + parseInt(limit));

      const formattedProducts = paginatedProducts.map(p => ({
        _id: p.id.toString(),
        name: p.name,
        brand: p.brand,
        description: p.description,
        price: p.price,
        originalPrice: p.originalPrice,
        images: [p.image],
        category: p.category,
        subcategory: p.subcategory,
        stock: p.inStock ? 100 : 0,
        ratings: { average: p.rating, count: p.reviews },
        badge: p.badge,
        createdAt: new Date().toISOString()
      }));

      return res.status(200).json({
        success: true,
        data: formattedProducts,
        pagination: {
          total: filteredProducts.length,
          page: parseInt(page),
          pages: Math.ceil(filteredProducts.length / parseInt(limit)),
        },
      });
    }

    try {
      let query = { isActive: true };

      // Filter by category
      if (category) {
        query.category = category;
      }
      
      if (req.query.subcategory) {
        query.subcategory = req.query.subcategory;
      }

      // Search functionality
      if (search) {
        query.$text = { $search: search };
      }

      const skip = (parseInt(page) - 1) * parseInt(limit);
      const products = await Product.find(query)
        .sort({ createdAt: -1 })
        .skip(skip)
        .limit(parseInt(limit));

      const total = await Product.countDocuments(query);

      res.status(200).json({
        success: true,
        data: products,
        pagination: {
          total,
          page: parseInt(page),
          pages: Math.ceil(total / parseInt(limit)),
        },
      });
    } catch (error) {
      res.status(500).json({ success: false, error: error.message });
    }
  } else if (method === 'POST') {
    try {
      await dbConnect();
    } catch (dbError) {
      return res.status(500).json({ success: false, error: "Database connection failed" });
    }

    try {
      // Check authentication
      const session = await getServerSession(req, res, authOptions);
      if (!session) {
        return res.status(401).json({ success: false, error: 'Not authenticated' });
      }

      // Check admin role
      if (session.user.role !== 'admin') {
        return res.status(403).json({ success: false, error: 'Admin access required' });
      }

      // Validate input
      const validatedData = productSchema.parse(req.body);

      const product = await Product.create(validatedData);
      res.status(201).json({ success: true, data: product });
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({
          success: false,
          error: 'Validation failed',
          details: error.errors,
        });
      }
      res.status(400).json({ success: false, error: error.message });
    }
  } else {
    res.status(405).json({ success: false, error: `Method ${method} not allowed` });
  }
}
